package com.shopsphere.config;import com.shopsphere.model.*;import com.shopsphere.repository.*;import org.springframework.boot.CommandLineRunner;import org.springframework.context.annotation.*;import org.springframework.security.crypto.password.PasswordEncoder;@Configuration public class DataSeeder{@Bean CommandLineRunner seed(UserRepository u,ProductRepository p,CategoryRepository c,PasswordEncoder e){return a->{if(u.findByEmail("admin@shop.com").isEmpty())u.save(new AppUser("Store Administrator","admin@shop.com",e.encode("Admin@123"),Role.ADMIN));if(u.findByEmail("customer@shop.com").isEmpty())u.save(new AppUser("Demo Customer","customer@shop.com",e.encode("Customer@123"),Role.CUSTOMER));if(c.count()==0){c.save(new Category("Electronics","Devices and useful tech"));c.save(new Category("Fashion","Wearable essentials"));c.save(new Category("Home","Home essentials"));}if(p.count()==0){String[][] rows={{"Studio Wireless Headphones","Electronics","2499","24","Immersive sound and all-day comfort."},{"Everyday Backpack","Fashion","1299","32","A durable companion for work and travel."},{"Smart Watch Pro","Electronics","3999","18","Track your day with smart insights."},{"Ceramic Coffee Set","Home","899","45","Beautiful cups for slower mornings."},{"Everyday Sneakers","Fashion","2199","21","Lightweight shoes for everyday use."},{"Desk Lamp","Home","1499","16","Warm adjustable lighting."}};for(String[]r:rows){Product x=new Product();x.setName(r[0]);x.setCategory(r[1]);x.setPrice(Double.valueOf(r[2]));x.setStock(Integer.valueOf(r[3]));x.setDescription(r[4]);p.save(x);}}};}}